          "act": 1,
          "title": "The Succession Void (January 1066)",
          "text": "<span class=\"para-ref\">[1.1]</span> On 5 January 1066, King Edward the Confessor died after reigning for twenty-four years. Edward left England in an existential crisis: he had died childless, leaving no direct heir to the throne. In Anglo-Saxon England, royal blood did not guarantee succession; the royal council, known as the **Witan**, held the constitutional right to elect the next monarch. Within twenty-four hours of Edward’s burial in Westminster Abbey, the Witan elected England’s wealthiest nobleman, **Harold Godwinson**, Earl of Wessex. Harold was crowned King Harold II, but his coronation ignited an international dynastic bloodbath.",
