          "act": 5,
          "title": "Local Fieldwork & Landscape Forensics: Portchester Castle",
          "text": "<span class=\"para-ref\">[2.5]</span> The physical anatomy of Norman subjugation remains dramatically visible along the Hampshire coastline at **Portchester Castle**. Rather than building from scratch, the Normans recognized the strategic value of the 3rd-century Roman Saxon Shore fort guarding Portsmouth Harbour. In the late 11th century, Norman engineers planted a colossal four-storey stone keep directly inside the north-west corner of the Roman flint walls, creating an inner bailey. At the same time, William audited the surrounding local manors in Domesday: the 1086 survey records that the King held Portchester (assessed at 2 hides with woodland for 10 pigs), while adjacent Fareham was assessed at 20 hides with two watermills and fisheries along the River Meon. These landscape forensics prove how military architecture and fiscal surveillance worked as two halves of a single imperial machine.",
          "image": "/images/medieval_england/plate_2_2_portchester_castle_keep.jpg",
          "image_alt": "High-angle view of the four-storey Norman stone Great Keep at Portchester Castle, Hampshire",
          "caption": "The imposing 12th-century Norman Great Keep at Portchester Castle, Hampshire, constructed within the monumental 3rd-century Roman Saxon Shore fort walls. The keep served as both an unassailable military strongpoint and a royal staging post for cross-Channel expeditions.",
          "isReversed": true,
