          "act": 1,
          "title": "The Black Death Catastrophe (1348–1350)",
          "text": "<span class=\"para-ref\">[5.1]</span> In the summer of 1348, a merchant ship from Gascony docked at Melcombe Regis in Dorset, carrying a lethal microscopic passenger: <em>Yersinia pestis</em>—the **Black Death**. Spreading through fleas on black rats and airborne respiratory droplets, the bubonic and pneumonic plagues swept across England with terrifying speed. Victims developed agonizing black swellings (buboes) in the groin and armpits, coughed black blood, and died within three days. By 1350, between 35% and 50% of England’s entire population had perished. Fields lay unharvested, cattle roamed through abandoned villages, and mass communal burial pits were dug outside city walls. The demographic foundations of feudalism had been shattered.",
          "image": "/images/medieval_england/plate_5_1_black_death_burial.jpg",
          "image_alt": "Illuminated miniature showing citizens of Tournai burying plague coffins in communal pits",
          "caption": "Citizens of Tournai carrying and burying plague coffins during the Black Death pandemic (c. 1350, Chronicle of Gilles Li Muisis, KBR MS 13076-77). The catastrophic mortality eradicated 30–50% of England's population between 1348 and 1350.",
          "isReversed": false,
